    public static int blinn_phong_attr_slot(string attr_name) {
        if (attr_name == "in_pos") {
            return 0;
        }
        if (attr_name == "in_normal") {
            return 1;
        }
        if (attr_name == "in_uv") {
            return 2;
        }
        if (attr_name == "in_tangent") {
